create table menu
(
    menu_id            bigint generated by default as identity
        primary key,
    menu_code          varchar(255) not null,
    available          varchar(255),
    access_role        varchar(20)
        constraint menu_access_role_check
            check ((access_role)::text = ANY
                   (ARRAY [('ROLE_ADMIN'::character varying)::text, ('ROLE_USER'::character varying)::text])),
    depth              integer,
    language           varchar(255),
    name_en            varchar(255),
    name_kor           varchar(255),
    sort_order         integer,
    parents_id         bigint
        constraint fk_menu_parents
            references menu
            on delete set null,
    root_id            bigint
        constraint fk_menu_root
            references menu
            on delete set null,
    created_by         varchar(255),
    created_date       timestamp(6) with time zone,
    last_modified_by   varchar(255),
    last_modified_date timestamp(6) with time zone
);

alter table menu
    owner to postgres;

